/* C API of the Rust port of `wrappers.c`, generated by rust-anything. */
#ifndef WRAPPERS_RS_H
#define WRAPPERS_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

uint64_t wrap_seqbuf_seq(uint64_t seed, int64_t bsz_i, int64_t nops_i);
uint64_t wrap_seqbuf_printf(uint64_t seed, int64_t bsz_i);
uint64_t wrap_seqbuf_hexdump(uint64_t seed, int64_t bsz_i, int64_t n_i);

/* The same functions under `rust_anything_` names, for shadow runs. */
uint64_t rust_anything_wrap_seqbuf_seq(uint64_t seed, int64_t bsz_i, int64_t nops_i);
uint64_t rust_anything_wrap_seqbuf_printf(uint64_t seed, int64_t bsz_i);
uint64_t rust_anything_wrap_seqbuf_hexdump(uint64_t seed, int64_t bsz_i, int64_t n_i);

#endif /* WRAPPERS_RS_H */
